/**
 * SlateExplanationOut
 *
 * The written "Why this could suit you" of a discovery's slate: at most one per
 * discovery, whatever view is shown. `run` is authoritative for its state; `written`
 * exists only once the run is complete, and a failed run's failure class says why there is
 * none. It changes no suggestion; the deterministic provenance beside it (each
 * suggestion's linked answers, searches and ESCO source) is what exports cite.
 */
export type SlateExplanationOut = {
    /**
     * Explanation Id
     */
    explanation_id: string;
    /**
     * Discovery Id
     */
    discovery_id: string;
    run: RunOut;
    /**
     * Can Retry
     *
     * The run failed before any request reached a model, so the person's Try again (`retry_failed`) may start the note afresh. False once a request was sent: the slate has had its one call, and Suggest again makes a new slate.
     */
    can_retry: boolean;
    written: WrittenExplanationOut | null;
};

/**
 * SlateOut
 *
 * A varied slate of up to six career hypotheses from the discovery's searches, computed
 * deterministically each time it is read, with every count that explains it. A title of
 * the person's own (their role, a target, or a search naming one) joins other work only by
 * shared essential skills, never by its words, and only once it names one occupation.
 */
export type SlateOut = {
    /**
     * Discovery Id
     */
    discovery_id: string;
    /**
     * Profile Version
     */
    profile_version: number;
    release: ReleaseRefOut;
    emphasis: Emphasis;
    /**
     * Target Size
     */
    target_size?: number;
    /**
     * Family Limit
     *
     * At most this many from one kind of work.
     */
    family_limit: number;
    /**
     * Suggestions
     */
    suggestions: Array<SuggestionOut>;
    /**
     * Fewer Reasons
     *
     * Why there are fewer than six, if there are, as facts the web words.
     */
    fewer_reasons: Array<NothingFound | FewMatched | KindsOfWorkShown | ExclusionsRemoved | TitleNotMatched | RoleNotMatched | TitleKeptAsOwn | TitleMatchedSeveral | NoSharedOccupation>;
    /**
     * Notes
     *
     * How the slate was made, as facts the web words: a control's effect, a changed ESCO release, answers not searched, answers that found no work or were too general to find it alone, what a join keeps, or fewer occupations to choose from than Careerwright aims for.
     */
    notes: Array<ReleaseChanged | OneWordWorkStyle | AnswerFoundNoWork | TooGeneral | JoinKeptBest | SmallPool | CastingWider | MoreDepth>;
    /**
     * Your confirmed salary floor's effect, as a hard filter; null with none.
     */
    salary_floor: SalaryFloorOut | null;
    ai_resilience_filter: AiResilienceFilterOut;
    /**
     * Pool Size
     *
     * Distinct occupations after folding near-duplicates.
     */
    pool_size: number;
    /**
     * Pool Target
     */
    pool_target?: [
        number,
        number
    ];
    /**
     * Beyond Pool Limit
     *
     * Occupations found but not kept: past a join's best 30 or the pool's bound.
     */
    beyond_pool_limit: number;
    excluded: ExcludedOut;
    /**
     * Queries
     *
     * Every search that ran, with its hits.
     */
    queries: Array<PoolQueryOut>;
    /**
     * Unsearchable Queries
     *
     * Queries with no searchable word.
     */
    unsearchable_queries: Array<string>;
    /**
     * Title Ideas
     *
     * Titles Careerwright thought of, each with what it did with it (`reason`): one ESCO holds as a label joins the slate's pool; one the UK job-title index lists (exactly) is a suggestion in its own list beside the slate, never in it; one no list holds is not yet found and never suggested.
     */
    title_ideas: Array<TitleIdea>;
    /**
     * Not Included
     *
     * Show why this wasn't included.
     */
    not_included: Array<NotIncludedOut>;
    /**
     * Unmatched Titles
     *
     * Titles of the person's own that Careerwright couldn't match to an occupation in ESCO (case, punctuation and plurals folded): nothing is joined to them.
     */
    unmatched_titles: Array<string>;
    /**
     * Ambiguous Titles
     *
     * Titles of the person's own that Careerwright matched to several occupations in ESCO: nothing is joined to them until the person chooses which one they mean.
     */
    ambiguous_titles: Array<string>;
    /**
     * Familiarity Known
     *
     * Whether the person's role or a target names an ESCO occupation, so Careerwright knows the kinds of work close to theirs: only then does a direction say it is different from their work (`less_familiar`).
     */
    familiarity_known: boolean;
};

